def design(feats) -> Design:
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    if p == 0 or n < 10 or len(np.unique(y)) < 2 or MAX_DRIVERS < 1:
        return Design(drivers=(), columns=(), products=(), loadings={})
    labs = list(dict.fromkeys(feats.stratum))
    S = np.array([[s == l for l in labs[1:]] for s in feats.stratum], float).reshape(n, -1)
    base = np.column_stack([np.ones(n), S])
    def ll(Z):
        A = np.column_stack([base, Z]) if Z is not None else base
        b = np.zeros(A.shape[1])
        for _ in range(40):
            eta = np.clip(A @ b, -30, 30); m = 1 / (1 + np.exp(-eta)); w = m * (1 - m) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            st = np.linalg.solve(H, A.T @ (y - m)); st *= min(1., 5. / (np.max(np.abs(st)) + 1e-12))
            b += st
            if np.max(np.abs(st)) < 1e-8: break
        eta = A @ b
        return float(np.sum(y * eta - np.logaddexp(0, eta)))
    def cols(sel, extra=()):
        z = [X[:, j] for j in sel] + [X[:, a] * X[:, b] for a, b in extra]
        return np.column_stack(z) if z else None
    R = np.nan_to_num(np.atleast_2d(np.corrcoef(X.T)))
    sel = []; cur = ll(None)
    for k in range(MAX_DRIVERS):
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel): continue
            v = ll(cols(sel + [j]))
            if best is None or v > best[0]: best = (v, j)
        if best is None or stats.chi2.sf(2 * (best[0] - cur), 1) > 0.1 / p: break
        v, j = best
        clus = [c for c in range(p) if abs(R[j, c]) >= 0.6 and c not in sel and not any(abs(R[c, s]) >= 0.6 for s in sel)]
        if len(clus) > 1:
            lls = {c: ll(cols(sel + [c])) for c in clus}
            near = [c for c in clus if lls[c] >= v - 2]
            j = max(near, key=lambda c: sum(R[c, d] ** 2 for d in clus)); v = lls[j]
        sel.append(j); cur = v
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [s for s in sel if s != j]
            if stats.chi2.sf(2 * (cur - ll(cols(rest))), 1) > 0.05 / p:
                sel = rest; cur = ll(cols(sel)); changed = True; break
    pa, pb = np.triu_indices(p); sc = np.empty(len(pa))
    r0 = y - y.mean()
    for start in range(0, len(pa), 1024):
        stop = start + 1024; P = X[:, pa[start:stop]] * X[:, pb[start:stop]]; P -= P.mean(0)
        sc[start:stop] = (P.T @ r0) ** 2 / (np.sum(P ** 2, 0) * y.mean() * (1 - y.mean()) + 1e-12)
    cand = []
    for i in np.argsort(-sc)[:15]:
        a, b = int(pa[i]), int(pb[i])
        mains = sorted(set(sel) | {a, b}); l0 = ll(cols(mains)); l1 = ll(cols(mains, [(a, b)]))
        pv = stats.chi2.sf(2 * (l1 - l0), 1)
        if pv < 0.01 / len(pa): cand.append((pv, a, b))
    prods = []
    for pv, a, b in sorted(cand):
        used = set(sel) | {c for pair in prods for c in pair} | {a, b}
        if len(prods) < 2 and len(used) <= MAX_DRIVERS and not any({a, b} & {c, d} for c, d in prods):
            prods.append((a, b))
    msel = list(sel)
    for a, b in prods:
        for c in (a, b):
            if c not in msel: msel.append(c)
    if prods:
        for c in list(msel):
            if c in sel: continue
            rest = [s for s in msel if s != c]
            if stats.chi2.sf(2 * (ll(cols(msel, prods)) - ll(cols(rest, prods))), 1) > 0.01 / p: msel = rest
    drivers = list(dict.fromkeys(list(sel) + [c for pair in prods for c in pair]))[:MAX_DRIVERS]
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in msel),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

